 try{if(isset($_FILES['gcash_qr'])&&($_FILES['gcash_qr']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$fn=secure_image_upload($_FILES['gcash_qr'],__DIR__.'/../uploads/payment_qr','gcash');$path='uploads/payment_qr/'.$fn;}if(isset($_POST['remove_qr']))$path=null;$pdo->prepare("UPDATE payment_settings SET gcash_account_name=?,gcash_number=?,gcash_qr_path=? WHERE id=1")->execute([$name,$number,$path]);log_activity($pdo,$u['id'],'Payment settings updated','GCash settings changed');flash('success','Payment settings saved.');redirect('payment-settings.php');}catch(Throwable $e){flash('error',$e->getMessage());redirect('payment-settings.php');}}
$s=$pdo->query("SELECT * FROM payment_settings WHERE id=1")->fetch();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Settings</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><header class="topbar"><div><button class="btn light mobile-toggle" data-nav-toggle>☰</button><div class="eyebrow">Configuration</div><h1>Payment settings.</h1></div></header><?php if($m=flash('success')):?><div class="notice"><?=e($m)?></div><?php endif;if($m=flash('error')):?><div class="notice error"><?=e($m)?></div><?php endif?><section class="grid two"><form class="card form-grid" method="post" enctype="multipart/form-data"><?=csrf_field()?><label class="field full"><span>GCash account name</span><input name="gcash_account_name" maxlength="160" value="<?=e($s['gcash_account_name']??'')?>" placeholder="Parish account name"></label><label class="field full"><span>GCash number</span><input name="gcash_number" maxlength="30" value="<?=e($s['gcash_number']??'')?>" placeholder="09XXXXXXXXX"></label><label class="field full"><span>GCash QR image</span><input type="file" name="gcash_qr" accept="image/png,image/jpeg,image/webp"><small class="muted">JPG, PNG or WEBP, maximum 5 MB.</small></label><?php if(!empty($s['gcash_qr_path'])):?><label class="field full"><span><input type="checkbox" name="remove_qr" value="1"> Remove current QR</span></label><?php endif?><div class="field full"><button class="btn">Save payment settings</button></div></form><div class="card"><h2>Parishioner preview</h2><?php if(!empty($s['gcash_qr_path'])):?><img class="payment-qr" src="../<?=e($s['gcash_qr_path'])?>" alt="GCash QR code"><?php else:?><div class="payment-placeholder">No GCash QR uploaded</div><?php endif?><p><b><?=e($s['gcash_account_name']?:'Account name not set')?></b><br><?=e($s['gcash_number']?:'GCash number not set')?></p><p class="muted">Online payment becomes available only when name, number and QR are all configured.</p></div></section></main></div><script src="../assets/js/script.js"></script></body></html>